mov     [word ptr bp+battle_unit_enchantments], dx
les     bx, [bp+battle_unit]
cmp     [es:bx+s_BATTLE_UNIT.movement_points], 3
jge     short @@Done_Almost
mov     ax, [word ptr bp+battle_unit_enchantments+2]
mov     dx, [word ptr bp+battle_unit_enchantments]
and     dx, 0
and     ax, UE_FLIGHT
or      dx, ax
jz      short @@Done_Almost
les     bx, [bp+battle_unit]
mov     [es:bx+s_BATTLE_UNIT.movement_points], 6

@@Done_Almost:
push    unit_idx
push    cs
call    near ptr Unit_Hit_Points
pop     cx
les     bx, [bp+battle_unit]
mov     [es:bx+s_BATTLE_UNIT.hits], al
pop     _DI_itr_players
pop     unit_idx
mov     sp, bp
pop     bp
retf
endp Battle_Unit_Regular_Stats



